# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ASAL ÇARPANLARA AYIRMA VE POZİTİF TAM BÖLEN SAYISI (10.3.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">ARİTMETİĞİN TEMEL TEOREMİ</text>\n  <text x="35" y="88" font-size="11.1" fill="#1e3a8a">• 1\'den büyük her A doğal sayısı, birbirinden</text>\n  <text x="45" y="104" font-size="10.8" fill="#1e3a8a">farklı p₁, p₂, ..., pₖ asal sayılarının kuvvetleri</text>\n  <text x="45" y="120" font-size="10.8" fill="#1e3a8a">çarpımı şeklinde tek türlü yazılır:</text>\n  <text x="35" y="146" font-size="11.5" font-weight="bold" fill="#1e3a8a">• A = p₁^a₁ · p₂^a₂ · ... · pₖ^aₖ</text>\n  <text x="35" y="172" font-size="10.8" fill="#1e3a8a">• Örnek: 180 = 2² · 3² · 5¹</text>\n  <text x="35" y="194" font-size="10.8" fill="#1e3a8a">• Asal çarpanları (bölenleri): 2, 3 ve 5 (3 tane)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">BÖLEN SAYISI BAĞINTILARI</text>\n  <text x="370" y="88" font-size="11.1" fill="#14532d">• Pozitif Tam Bölen Sayısı (PBS):</text>\n  <text x="380" y="106" font-size="11.2" font-weight="bold" fill="#14532d">PBS(A) = (a₁ + 1) · (a₂ + 1) · ... · (aₖ + 1)</text>\n  <text x="370" y="130" font-size="10.8" fill="#14532d">• 180 için PBS = (2 + 1)·(2 + 1)·(1 + 1) = 3·3·2 = 18</text>\n  <text x="370" y="154" font-size="10.8" fill="#14532d">• Negatif Tam Bölen Sayısı (NBS) = PBS = 18</text>\n  <text x="370" y="176" font-size="10.8" fill="#14532d">• Tam Bölen Sayısı = 2 · PBS = 36</text>\n  <text x="370" y="198" font-size="10.8" fill="#14532d">• Asal Olmayan Pozitif Bölen = PBS - k = 18 - 3 = 15</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Özel Örüntü: Tam kare doğal sayıların (1, 4, 9, 16, 25, 36...) pozitif tam bölen sayısı (PBS) daima TEK sayıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EBOB VE EKOK KAVRAMLARI İLE TEMEL ÖZELLİKLERİ (10.3.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#92400e">EBOB VE EKOK BULMA KURALI</text>\n  <text x="35" y="88" font-size="10.8" fill="#78350f">• Asal çarpanlarına ayrılmış iki doğal sayıda:</text>\n  <text x="35" y="112" font-size="10.8" fill="#78350f">• EBOB(A, B): Ortak asal çarpanlardan üssü</text>\n  <text x="45" y="128" font-size="10.8" font-weight="bold" fill="#78350f">en küçük olanların çarpımıdır.</text>\n  <text x="35" y="152" font-size="10.8" fill="#78350f">• EKOK(A, B): Ortak asal çarpanlardan üssü</text>\n  <text x="45" y="168" font-size="10.8" font-weight="bold" fill="#78350f">en büyük olanlar ile ortak olmayan asal</text>\n  <text x="45" y="184" font-size="10.8" font-weight="bold" fill="#78350f">çarpanların tamamının çarpımıdır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">TEMEL MUHAKEME ÖNERMELERİ</text>\n  <text x="370" y="88" font-size="10.8" font-weight="bold" fill="#581c87">• A · B = EBOB(A, B) · EKOK(A, B)  (İki sayı için!)</text>\n  <text x="370" y="112" font-size="10.8" fill="#581c87">• EBOB(A, B) ≤ min(A, B) ≤ max(A, B) ≤ EKOK(A, B)</text>\n  <text x="370" y="136" font-size="10.8" fill="#581c87">• A ve B aralarında asal ise:</text>\n  <text x="380" y="152" font-size="10.8" font-weight="bold" fill="#581c87">EBOB(A, B) = 1  ve  EKOK(A, B) = A · B</text>\n  <text x="370" y="176" font-size="10.8" fill="#581c87">• B sayısı A\'nın tam katı ise (A | B):</text>\n  <text x="380" y="192" font-size="10.8" font-weight="bold" fill="#581c87">EBOB(A, B) = A  ve  EKOK(A, B) = B</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İki doğal sayının tüm ortak bölenlerinin kümesi, bu iki sayının EBOB\'unun bölenleri kümesine eşittir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GERÇEK YAŞAM PROBLEMLERİNDE EBOB VE EKOK MODELLEMESİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">BÜYÜKTEN KÜÇÜĞE PARÇALAMA ⟶ EBOB</text>\n  <text x="35" y="88" font-size="10.8" fill="#7c2d12">• Çuvallardaki ürünleri eşit hacimli poşetlere</text>\n  <text x="45" y="104" font-size="10.8" fill="#7c2d12">veya şişelere hiç artmayacak şekilde bölüştürme,</text>\n  <text x="35" y="128" font-size="10.8" fill="#7c2d12">• Tarlanın/bahçenin etrafına eşit aralıklarla</text>\n  <text x="45" y="144" font-size="10.8" fill="#7c2d12">en az sayıda ağaç veya direk dikme,</text>\n  <text x="35" y="168" font-size="10.8" fill="#7c2d12">• Büyük dikdörtgen/prizmayı eş karelere/küplere</text>\n  <text x="45" y="184" font-size="10.8" fill="#7c2d12">ayırma problemlerinde EBOB kullanılır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#065f46">KÜÇÜKTEN BÜYÜĞE BİRLEŞTİRME ⟶ EKOK</text>\n  <text x="370" y="88" font-size="10.8" fill="#064e3b">• Farklı periyotlarla çalan zillerin, nöbet tutan</text>\n  <text x="380" y="104" font-size="10.8" fill="#064e3b">doktorların veya sefer yapan araçların tekrar</text>\n  <text x="380" y="120" font-size="10.8" fill="#064e3b">aynı anda karşılaşma süresini bulma,</text>\n  <text x="370" y="144" font-size="10.8" fill="#064e3b">• Küçük dikdörtgen fayanslardan/tuğlalardan</text>\n  <text x="380" y="160" font-size="10.8" fill="#064e3b">en küçük kare/küp oluşturma,</text>\n  <text x="370" y="184" font-size="10.8" fill="#064e3b">• Kalanlı bölünme problemlerinde EKOK kullanılır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kapalı bir şeklin (üçgen, dikdörtgen) çevresine eşit d aralığıyla dikilen direk sayısı = Çevre / d bağıntısıyla bulunur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
